{"path": "forth.py", "content": "class StackUnderflowError(Exception):
    """Exception raised when the stack has too few items for an operation.

    message: explanation of the error.
    """

    def __init__(self, message):
        super().__init__(message)
        self.message = message


def _is_number(token):
    return token.lstrip("-").isdigit() and token.count("-") <= 1 and (
        not token.startswith("-") or len(token) > 1
    ) and "-" not in token[1:]


def _pop(stack, count):
    if len(stack) < count:
        raise StackUnderflowError("Insufficient number of items in stack")
    values = stack[-count:]
    del stack[-count:]
    return values


def _add(stack):
    a, b = _pop(stack, 2)
    stack.append(a + b)


def _sub(stack):
    a, b = _pop(stack, 2)
    stack.append(a - b)


def _mul(stack):
    a, b = _pop(stack, 2)
    stack.append(a * b)


def _div(stack):
    a, b = _pop(stack, 2)
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    quotient = abs(a) // abs(b)
    stack.append(quotient if (a < 0) == (b < 0) else -quotient)


def _dup(stack):
    (a,) = _pop(stack, 1)
    stack.extend([a, a])


def _drop(stack):
    _pop(stack, 1)


def _swap(stack):
    a, b = _pop(stack, 2)
    stack.extend([b, a])


def _over(stack):
    a, b = _pop(stack, 2)
    stack.extend([a, b, a])


BUILTINS = {
    "+": _add,
    "-": _sub,
    "*": _mul,
    "/": _div,
    "dup": _dup,
    "drop": _drop,
    "swap": _swap,
    "over": _over,
}


def evaluate(input_data):
    """Evaluate a list of Forth source lines and return the resulting stack."""
    stack = []
    # User definitions map a word to its fully expanded token list.
    definitions = {}

    tokens = []
    for line in input_data:
        tokens.extend(line.lower().split())

    def expand(token):
        if token in definitions:
            return list(definitions[token])
        return [token]

    index = 0
    while index < len(tokens):
        token = tokens[index]
        index += 1

        if token == ":":
            try:
                end = tokens.index(";", index)
            except ValueError:
                raise ValueError("undefined operation") from None
            if end == index:
                raise ValueError("undefined operation")
            name = tokens[index]
            if _is_number(name):
                raise ValueError("illegal operation")
            body = []
            for word in tokens[index + 1:end]:
                body.extend(expand(word))
            definitions[name] = body
            index = end + 1
            continue

        for word in expand(token):
            if _is_number(word):
                stack.append(int(word))
            elif word in BUILTINS:
                BUILTINS[word](stack)
            else:
                raise ValueError("undefined operation")

    return stack
